insert into public.changes (headline, detail, source_url, effective_date) values
  ('CMMC Phase II suspended', 'The November 10, 2026 deadline for mandatory Level 2 third-party (C3PAO) certification is no longer in effect. Level 1 self-assessment and DFARS 252.204-7012/7019/7020 remain in force.', 'https://dodcio.defense.gov/Portals/0/Documents/Library/ImplementingSuspensionCMMC-PhaseII.pdf', '2026-07-13'),
  ('8(a) social-disadvantage presumption under rule change', '⟦VERIFY: high-priority Regulatory Watch. Confirm the rule took effect as scheduled and check for litigation before publishing anything in the past tense.⟧', 'https://www.sba.gov/article/2026/06/11/sba-reforms-8a-business-development-program-end-racial-discrimination-federal-contracting', '2026-09-10'),
  ('Department of War rebrand', 'DoD is officially the Department of War. Sites and portal URLs are mid-transition across dodcio.defense.gov, war.gov, and business.defense.gov.', 'https://www.whitehouse.gov/presidential-actions/2025/09/restoring-the-united-states-department-of-war/', '2025-09-01');
